"use client";

// src/components/codeEditor.tsx — ported by value from packages/bbox-ui's
// CodeMirror field, reconciling two lineages that diverged on main:
//
// - packages/bbox-ui/src/codeField.tsx (592 lines, current on main) is the
//   engine this keeps almost verbatim: the write policy (`onWrite` per
//   keystroke via `codeEditorGesture.ts`'s `FieldGesture`), the single-line
//   guard, the Enter/Escape exit contract, the external-value-sync effect,
//   the wheel/pointerdown host-interop effects.
// - packages/bbox-ui/src/codeBlock.tsx (900 lines, deleted on main by
//   368a524 "CodeBlock becomes CodeField", recovered from
//   claude/code-block-primitive) is where `lineNumbers`, the `columns` →
//   pixel width maths (now `codeEditorLayout.ts`), and the `overflow`
//   clip/wrap/scroll modes came from — main's rename trimmed all three
//   along with the `grammar`/`mode`/rows machinery.
//
// Dropped entirely, on both sides: `grammar` (slot decorations +
// completion — `codeGrammar.ts`/`completionMenu.ts`), the rendered/source
// `mode` toggle and `CodeEditorRows` (`codeFieldRows.tsx`/`codeBlockRows`),
// `flatten`/`codeBlockUnits.ts`'s Python-unit folding, and the `look`
// preset ladder (`codeBlock.presets.ts`) — this app has no FieldSpec /
// appearance-cascade machinery to hang any of that on (see CLAUDE.md).
// `language` survives as its own prop (a raw CodeMirror `LanguageSupport`)
// specifically BECAUSE dropping `grammar` wholesale would also have
// dropped syntax highlighting, which the PseudoCode story plainly needs.
//
// `tooltipParent`/the completion popup's `tooltips()` extension are also
// dropped — nothing here ever opens a tooltip without `grammar`'s
// completion source, so parenting one was dead plumbing.

import {
  copyLineDown,
  copyLineUp,
  defaultKeymap,
  history,
  historyKeymap,
  moveLineDown,
  moveLineUp,
} from "@codemirror/commands";
import { syntaxHighlighting, type LanguageSupport } from "@codemirror/language";
import {
  Compartment,
  EditorState,
  Prec,
  type Extension,
} from "@codemirror/state";
import {
  EditorView,
  keymap,
  lineNumbers as lineNumbersExtension,
  placeholder as placeholderExtension,
} from "@codemirror/view";
import {
  forwardRef,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  type CSSProperties,
} from "react";

import "./codeEditor.css";

import { FieldGesture } from "./codeEditorGesture";
import { externalSync, singleLineGuard } from "./codeEditorGuards";
import { codeEditorHighlightStyle } from "./codeEditorHighlight";
import { codeEditorWidthPx } from "./codeEditorLayout";
import { codeEditorThemeVars, type CodeEditorTheme } from "./codeEditorTheme";

/** The horizontal padding baked into `.bbox-code-editor` in codeEditor.css —
 * kept as a constant here too so `columns`'s pixel maths (codeEditorLayout.ts)
 * matches what actually renders, rather than guessing the stylesheet's number. */
const PADDING_X = 6;

/** What a line wider than the box does. `clip` (the default — an <input>-like
 * port label: cut at the edge, no bar) and `scroll` (a horizontal scrollbar,
 * CodeMirror's own scroller — the IDE feel Zach's screenshot wants) both keep
 * `columns`' fixed width; `wrap` folds the line onto new rows instead and
 * ignores `columns` for width purposes since the text no longer runs past it. */
export type CodeEditorOverflow = "clip" | "wrap" | "scroll";

export interface CodeEditorProps {
  /** The document. The field follows it whenever nobody is editing. */
  value: string;
  /** Write, per keystroke — the field's one write policy (see `codeEditorGesture.ts`). */
  onWrite(value: string): void;
  /** Open one undo step so an edit is one Ctrl+Z, not one per character. */
  beginEdit?(): void;
  /** The commit boundary — one call per gesture, however the field was left. */
  onEditEnd?(value: string, startValue: string): void;
  /** The syntax parser, e.g. `python()`/`javascript()`/`json()`. Omit for plain text. */
  language?: LanguageSupport;
  /**
   * A VS Code syntax palette (codeEditorTheme.ts) — an id resolved against
   * `CODE_EDITOR_THEMES`, or a `CodeEditorTheme` object directly. Applied
   * as CSS custom properties on the root, UNDER any caller `style` (a
   * caller override still wins). Omit, or pass an id that doesn't match
   * any known theme, for the ambient default palette — never blanks the
   * editor.
   */
  theme?: CodeEditorTheme | string;
  /**
   * A lane/document: several lines, Enter inserts a line, Alt+↑/↓ move one,
   * Shift+Alt+↓ copies one (CodeMirror's default keymap); Ctrl/Cmd+Enter is
   * the exit that Enter is for a single line. `false` (the default): one
   * line — a typed or pasted newline is dropped rather than growing the box.
   */
  multiline?: boolean;
  /** The line-number gutter. Off by default (a bare port-label line has nothing to number). */
  lineNumbers?: boolean;
  /** What a line wider than the box does. Defaults to `"clip"`. */
  overflow?: CodeEditorOverflow;
  /**
   * Characters across. `> 0` fixes the box's width to that many mono cells
   * plus padding (and the gutter when `lineNumbers` is on) — see
   * `codeEditorLayout.ts`'s `codeEditorWidthPx`. `0` (the default) fills
   * whatever the host gives. Ignored when `overflow === "wrap"` — a
   * wrapped line has no fixed width to overflow.
   */
  columns?: number;
  /** The type size, in px — also what `columns`'s pixel maths is computed against. */
  fontSizePx?: number;
  /** Pin every line to this height so lines can sit on a host's own rows. */
  lineHeightPx?: number;
  align?: "left" | "right";
  disabled?: boolean;
  placeholder?: string;
  ariaLabel?: string;
  ariaDescribedBy?: string;
  ariaInvalid?: boolean;
  className?: string;
  testId?: string;
  style?: CSSProperties;
  /** Take focus on mount; `'select'` also selects the whole line/document. */
  autoFocus?: boolean | "select";
  /** With `autoFocus`, put the caret here instead of selecting everything. */
  cursorAt?: number;
  /** With `autoFocus`, select exactly this range. */
  selectRange?: { from: number; to: number };
  /**
   * Enter (single-line) / Ctrl+Enter (multi) and Escape both end the
   * gesture by leaving the field (the value is never discarded — Ctrl+Z is
   * the retract). A host that owns its own editing session supplies its
   * own exits instead of the default `leave`.
   */
  onEnter?(): void;
  onEscape?(): void;
  onViewReady?(view: EditorView): void;
}

export interface CodeEditorHandle {
  setCaret(offset: number): void;
  focus(): void;
}

/**
 * `CodeEditor` — the code text box: one line (the shape `LabeledPort`'s
 * label needs) or a multi-line lane/document (the shape the multiline port
 * editor needs), the same engine wearing different props. A real CodeMirror
 * document, so highlighting, IME, undo and the caret all come from one
 * mature engine rather than a mirror-div.
 *
 * WHY `CodeEditor` and not `CodeField`/`CodeBlock` (Zach, 2026-09-16: "its
 * clear that refers to the component, CodeMirror is the library"): `Code`
 * alone collides with nothing here, `Field`/`Block` each already carry a
 * different meaning elsewhere in bbox-ui (`Block` is the canvas node this
 * app also ships; `CodeBlock` collides with a real Code node on the
 * SystemSketch canvas) — `Editor` says what it is without borrowing either.
 */
export const CodeEditor = forwardRef<CodeEditorHandle, CodeEditorProps>(function CodeEditor({
  value,
  onWrite,
  beginEdit,
  onEditEnd,
  language,
  theme,
  multiline = false,
  lineNumbers = false,
  overflow = "clip",
  columns = 0,
  fontSizePx = 13,
  lineHeightPx,
  align = "left",
  disabled = false,
  placeholder,
  ariaLabel,
  ariaDescribedBy,
  ariaInvalid,
  className,
  testId,
  style,
  autoFocus = false,
  cursorAt,
  selectRange,
  onEnter,
  onEscape,
  onViewReady,
}, ref) {
  const wrap = overflow === "wrap";
  const hostRef = useRef<HTMLDivElement>(null);
  const viewRef = useRef<EditorView | null>(null);
  const languageCompartment = useRef(new Compartment());
  const gutterCompartment = useRef(new Compartment());
  const editableCompartment = useRef(new Compartment());
  const placeholderCompartment = useRef(new Compartment());
  const metricsCompartment = useRef(new Compartment());

  const latest = useRef({
    onWrite,
    beginEdit,
    onEditEnd,
    onEnter,
    onEscape,
    value,
    disabled,
    multiline,
  });
  latest.current = {
    onWrite,
    beginEdit,
    onEditEnd,
    onEnter,
    onEscape,
    value,
    disabled,
    multiline,
  };

  const metrics = (): Extension => [
    EditorView.theme({
      ...(lineHeightPx
        ? { ".cm-line": { lineHeight: `${lineHeightPx}px`, height: `${lineHeightPx}px` } }
        : {}),
      ...(align === "right" ? { ".cm-content": { textAlign: "right" } } : {}),
    }),
    ...(wrap ? [EditorView.lineWrapping] : []),
  ];

  const gestureRef = useRef<FieldGesture | null>(null);
  if (!gestureRef.current) {
    gestureRef.current = new FieldGesture(
      {
        write: (next) => latest.current.onWrite(next),
        begin: () => latest.current.beginEdit?.(),
        end: (next, start) => latest.current.onEditEnd?.(next, start),
      },
      "live",
    );
  }
  const gesture = gestureRef.current;

  const leave = (view: EditorView) => {
    view.contentDOM.blur();
    gesture.commit();
  };

  useImperativeHandle(ref, () => ({
    setCaret: (offset) => {
      const view = viewRef.current;
      if (!view) return;
      const anchor = Math.max(0, Math.min(offset, view.state.doc.length));
      view.dispatch({ selection: { anchor }, effects: EditorView.scrollIntoView(anchor) });
      view.focus();
    },
    focus: () => viewRef.current?.focus(),
  }), []);

  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const view = new EditorView({
      state: EditorState.create({
        doc: value,
        extensions: [
          history(),
          // Enter and Escape are the field's exits, handled on the raw
          // event so the keystroke can be STOPPED — see codeField.tsx's own
          // WHY (unchanged here; there is no completion popup any more to
          // give first refusal to, so that branch is simply gone).
          Prec.high(
            EditorView.domEventHandlers({
              keydown: (event, target) => {
                if (event.isComposing) return false;
                if (event.key !== "Enter" && event.key !== "Escape") return false;
                const modifierEnter = event.key === "Enter" && (event.ctrlKey || event.metaKey);
                if (event.key === "Enter" && latest.current.multiline && !modifierEnter) {
                  return false;
                }
                event.preventDefault();
                event.stopPropagation();
                const exit = event.key === "Enter" ? latest.current.onEnter : latest.current.onEscape;
                if (exit) exit();
                else leave(target);
                return true;
              },
            }),
          ),
          singleLineGuard(() => latest.current.multiline),
          keymap.of([
            { key: "Ctrl-ArrowUp", run: moveLineUp },
            { key: "Ctrl-ArrowDown", run: moveLineDown },
            { key: "Ctrl-Shift-ArrowUp", run: copyLineUp },
            { key: "Ctrl-Shift-ArrowDown", run: copyLineDown },
            ...defaultKeymap,
            ...historyKeymap,
          ]),
          languageCompartment.current.of(language ?? []),
          // WHY `codeEditorHighlightStyle` and not the stock `classHighlighter`
          // this used to mount directly: see codeEditorHighlight.ts's own WHY.
          syntaxHighlighting(codeEditorHighlightStyle),
          gutterCompartment.current.of(lineNumbers ? [lineNumbersExtension()] : []),
          editableCompartment.current.of(EditorView.editable.of(!disabled)),
          placeholderCompartment.current.of(placeholder ? placeholderExtension(placeholder) : []),
          metricsCompartment.current.of(metrics()),
          EditorView.inputHandler.of((target, from, to, insertedText) => {
            if (latest.current.multiline || !/[\r\n]/.test(insertedText)) return false;
            const cleaned = insertedText.replace(/[\r\n]+/g, "");
            target.dispatch({
              changes: { from, to, insert: cleaned },
              selection: { anchor: from + cleaned.length },
            });
            return true;
          }),
          EditorView.updateListener.of((update) => {
            if (!update.docChanged) return;
            if (update.transactions.every((tr) => tr.annotation(externalSync))) return;
            const text = update.state.doc.toString();
            gesture.focus(latest.current.value);
            gesture.change(text);
          }),
          EditorView.domEventHandlers({
            focus: () => {
              if (latest.current.disabled) return;
              gesture.focus(latest.current.value);
            },
            blur: () => {
              globalThis.setTimeout(() => {
                const current = viewRef.current;
                if (current && !current.hasFocus) gesture.commit();
              }, 0);
            },
          }),
        ],
      }),
      parent: host,
    });
    viewRef.current = view;
    onViewReady?.(view);
    let frame = 0;
    if (autoFocus) {
      const take = () => {
        if (view.hasFocus || !viewRef.current) return;
        view.focus();
        const length = view.state.doc.length;
        if (selectRange) {
          const anchor = Math.max(0, Math.min(selectRange.from, length));
          const head = Math.max(anchor, Math.min(selectRange.to, length));
          view.dispatch({ selection: { anchor, head } });
        } else if (cursorAt !== undefined) {
          const anchor = Math.max(0, Math.min(cursorAt, length));
          view.dispatch({ selection: { anchor } });
        } else if (autoFocus === "select") {
          view.dispatch({ selection: { anchor: 0, head: view.state.doc.length } });
        }
      };
      take();
      frame = requestAnimationFrame(take);
    }
    return () => {
      cancelAnimationFrame(frame);
      viewRef.current = null;
      view.destroy();
    };
    // One mount for the field's lifetime; content, language, chrome and
    // editability flow through compartments and dispatches so a re-render
    // never tears the document down mid-gesture.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // The document follows the store whenever nobody is typing in it.
  useLayoutEffect(() => {
    const view = viewRef.current;
    if (!view || view.state.doc.toString() === value) return;
    if (gesture.isEditing && view.hasFocus) return;
    view.dispatch({
      changes: { from: 0, to: view.state.doc.length, insert: value },
      annotations: externalSync.of(true),
    });
  }, [value, gesture]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({ effects: languageCompartment.current.reconfigure(language ?? []) });
  }, [language]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({
      effects: gutterCompartment.current.reconfigure(lineNumbers ? [lineNumbersExtension()] : []),
    });
  }, [lineNumbers]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({
      effects: editableCompartment.current.reconfigure(EditorView.editable.of(!disabled)),
    });
  }, [disabled]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({ effects: metricsCompartment.current.reconfigure(metrics()) });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lineHeightPx, align, wrap]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({
      effects: placeholderCompartment.current.reconfigure(
        placeholder ? placeholderExtension(placeholder) : [],
      ),
    });
  }, [placeholder]);

  // See codeField.tsx's own WHY: a canvas host typically swallows the
  // native pointerdown/wheel a plain blur/scroll would rely on.
  useLayoutEffect(() => {
    const handlePointerDown = (event: PointerEvent) => {
      const host = hostRef.current;
      const view = viewRef.current;
      if (!host || !view || !view.hasFocus) return;
      if (event.target instanceof Node && host.contains(event.target)) return;
      leave(view);
    };
    document.addEventListener("pointerdown", handlePointerDown, true);
    return () => document.removeEventListener("pointerdown", handlePointerDown, true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const handleWheel = (event: WheelEvent) => {
      if (viewRef.current?.hasFocus) event.stopPropagation();
    };
    host.addEventListener("wheel", handleWheel, { passive: false });
    return () => host.removeEventListener("wheel", handleWheel);
  }, []);

  useLayoutEffect(() => () => gesture.commit(), [gesture]);

  const width = wrap ? undefined : codeEditorWidthPx(columns, fontSizePx, lineNumbers, PADDING_X, PADDING_X);

  const boxStyle: CSSProperties = {
    fontSize: fontSizePx,
    ...(width !== undefined ? { width } : {}),
  };

  return (
    <div
      data-slot="code-editor"
      data-multiline={multiline}
      data-line-numbers={lineNumbers}
      data-overflow={overflow}
      data-language={language ? "set" : undefined}
      data-theme={typeof theme === "string" ? theme : theme?.id}
      className={`bbox-code-editor bbox-code-tokens${className ? ` ${className}` : ""}`}
      ref={hostRef}
      role="textbox"
      aria-label={ariaLabel}
      aria-describedby={ariaDescribedBy}
      aria-invalid={ariaInvalid ? true : undefined}
      aria-disabled={disabled ? true : undefined}
      aria-multiline={multiline ? true : undefined}
      data-testid={testId}
      // Theme vars sit BETWEEN boxStyle and the caller's own `style` — a
      // caller override (including a caller's own --bbox-tok-* variable)
      // still wins over the theme, same as it always won over boxStyle.
      style={{ ...boxStyle, ...codeEditorThemeVars(theme), ...style }}
      onPointerDown={(event) => event.stopPropagation()}
      onClick={(event) => event.stopPropagation()}
      onDoubleClick={(event) => event.stopPropagation()}
    />
  );
});

// src/components/codeEditorGesture.ts — ported by value from
// packages/bbox-ui/src/fieldGesture.ts, unchanged apart from doc references
// (CodeField → CodeEditor). Pure state machine, no CodeMirror/React import,
// so it carries over with nothing to strip.

/**
 * The live-commit contract `CodeEditor` follows.
 *
 * WHY a gesture object instead of "call `onWrite` on change, `onEditEnd` on
 * blur": a text field's edit is a *gesture* with three boundaries — it
 * begins, it produces values, and it ends exactly once — and how the field
 * was left (blur, Enter, Escape, the host unmounting the panel) only
 * decides *when* the gesture ends, never *whether* the value survives. The
 * browser will not tell you about the last one: no `blur` fires for a
 * focused element removed from the DOM, so a naive commit-on-blur field
 * silently drops whatever was typed the instant its panel unmounts. This
 * class is driven from the React lifecycle instead (`CodeEditor`'s unmount
 * effect calls `commit()`), where that boundary is observable.
 *
 * Two write policies, both loss-free:
 *
 * - `live` — every keystroke writes straight into the caller's store, so
 *   the store is the only copy of the text and there is nothing left to
 *   lose. `CodeEditor` uses this exclusively.
 * - `exit` — the value is buffered and written once, at the end boundary,
 *   for a write that is genuinely expensive. Still loss-free, because
 *   unmount is itself an end boundary.
 *
 * `begin` fires lazily, on the first keystroke that actually changes the
 * value, so a field that was merely focused leaves no trace in undo
 * history. `end` is the commit boundary a caller can hang a semantic
 * "rename" or a debounced round trip off, without the live write ever
 * having to wait for it.
 */

export type FieldCommitMode = "live" | "exit";

export interface FieldGestureHooks {
  /** Write the value. Per keystroke in `live`, once at the end in `exit`. */
  write(value: string): void;
  /**
   * Open one undoable step. Called lazily — on the first keystroke that
   * really changes the value — so merely focusing a field leaves no trace.
   */
  begin?(): void;
  /** The commit boundary. Fires exactly once per gesture, whatever ended it. */
  end?(value: string, startValue: string): void;
}

export class FieldGesture {
  mode: FieldCommitMode;

  private readonly hooks: FieldGestureHooks;
  private editing = false;
  private began = false;
  private start = "";
  private current = "";

  constructor(hooks: FieldGestureHooks, mode: FieldCommitMode = "live") {
    this.hooks = hooks;
    this.mode = mode;
  }

  get isEditing(): boolean {
    return this.editing;
  }

  get startValue(): string {
    return this.start;
  }

  get value(): string {
    return this.current;
  }

  /** Enter the field. Idempotent: re-entering keeps the original pre-edit value. */
  focus(value: string): void {
    if (this.editing) return;
    this.editing = true;
    this.began = false;
    this.start = value;
    this.current = value;
  }

  /** One keystroke, paste, or IME commit. */
  change(value: string): void {
    if (!this.editing) this.focus(this.current);
    if (value === this.current) return;
    this.current = value;
    if (this.mode !== "live") return;
    this.ensureBegun();
    this.hooks.write(value);
  }

  /**
   * End the gesture and keep the value. Every exit route calls this — blur,
   * Enter, Escape, and the unmount cleanup — so it must stay idempotent.
   */
  commit(): void {
    if (!this.editing) return;
    if (this.mode === "exit" && this.current !== this.start) {
      this.ensureBegun();
      this.hooks.write(this.current);
    }
    const value = this.current;
    const start = this.start;
    this.editing = false;
    this.began = false;
    this.hooks.end?.(value, start);
  }

  private ensureBegun(): void {
    if (this.began) return;
    this.began = true;
    this.hooks.begin?.();
  }
}

// src/components/codeEditorGuards.ts — ported by value from
// packages/bbox-ui/src/codeFieldGuards.ts, unchanged apart from doc
// references (CodeField → CodeEditor). Pure CodeMirror state logic, no
// React, nothing to strip.

import {
  Annotation,
  EditorState,
  Transaction,
  type AnnotationType,
  type Extension,
} from "@codemirror/state";

/**
 * Marks `CodeEditor`'s own imperative doc swaps (the `value`-prop sync) so
 * the change listener never echoes them back as typing. Lives here, not in
 * `codeEditor.tsx`, so `singleLineGuard` below can recognise and re-apply it
 * on a transaction it has to rebuild — annotations are not part of
 * CodeMirror's public `Transaction` surface (only `.annotation(type)` for a
 * type you already know to ask for, never an enumerable list), so the only
 * ones a filter can honestly preserve are ones it knows about by name.
 */
export const externalSync = Annotation.define<boolean>();

/**
 * The named annotations this guard knows how to detect and re-apply on a
 * transaction it has to rebuild: CodeMirror's own `Transaction.time` /
 * `userEvent` / `addToHistory` / `remote`, plus `externalSync` above.
 *
 * WHY this matters beyond bookkeeping: `userEvent` and `addToHistory` are
 * what `history()` groups undo steps by. Losing them made a rebuilt
 * transaction look like an ORDINARY edit with no origin and no history
 * opinion — inside CodeMirror's 500ms `newGroupDelay`, that merged
 * silently into whatever adjacent edit was already open. Type `P`, then
 * paste `a\nb` (copying a lane line with an empty selection is linewise
 * and carries a trailing `\n`, so this is common here): one Ctrl+Z used to
 * discard the typing AND the paste together, leaving `t: ` instead of
 * undoing the paste alone. `time` matters too — it feeds the SAME grouping
 * window, so a rebuilt transaction stamped with a fresh `Date.now()`
 * instead of the original's timestamp can drift outside the window the
 * original edit was actually inside.
 */
function knownAnnotations(tr: Transaction): Annotation<unknown>[] {
  const carried: Annotation<unknown>[] = [];
  function add<T>(type: AnnotationType<T>): void {
    const value = tr.annotation(type);
    if (value !== undefined) carried.push(type.of(value));
  }
  add(Transaction.time);
  add(Transaction.userEvent);
  add(Transaction.addToHistory);
  add(Transaction.remote);
  add(externalSync);
  return carried;
}

/** How many `\r`/`\n` characters sit in `text` before `pos` — the amount a position must shift left to land on the equivalent spot once those characters are removed. */
function newlinesBefore(text: string, pos: number): number {
  let count = 0;
  for (let i = 0; i < pos; i++) {
    const code = text.charCodeAt(i);
    if (code === 10 || code === 13) count++;
  }
  return count;
}

/**
 * A single-line `CodeEditor` must never contain a newline, by ANY path —
 * not just typed or pasted text (`EditorView.inputHandler` catches that
 * one, and stays for the tighter cursor placement it can do on a normal
 * keystroke) but also a COMMAND that inserts one directly, like
 * `defaultKeymap`'s `insertBlankLine` (reachable on Ctrl/Cmd+Enter when a
 * completion popup happens to be open and swallows the field's own exit
 * binding first). A `transactionFilter` sees every transaction regardless
 * of what produced it, so this is the actual guarantee, not a best effort
 * at the input layer.
 *
 * Things earlier passes at this got wrong, all fixed here:
 *
 * - The caret was clamped to the CLEANED text's length instead of shifted
 *   by how many stripped characters sat ahead of it.
 * - The replacement spec silently dropped every annotation and effect —
 *   `externalSync` (an external value-sync misread as typing) and, worse,
 *   CodeMirror's OWN `userEvent`/`addToHistory`/`time` (undo-grouping
 *   corruption — see `knownAnnotations`'s doc). `effects` are forwarded
 *   unconditionally (a plain array on `Transaction`, unlike annotations,
 *   which have no generic enumerable list); `scrollIntoView` likewise.
 * - A transaction that, once cleaned, changes the DOCUMENT not at all
 *   (pasting a bare `"\n"`, or pasting text that survives cleaning back to
 *   exactly what a replaced selection already said) either dispatched a
 *   pointless full document-replace (a dead undo step) or, at the other
 *   extreme, dropped the transaction so completely that a REPLACED
 *   SELECTION was left standing open instead of collapsed to where the
 *   paste actually ended — the very next keystroke would have overwritten
 *   the pasted text a second time. Both are handled by always computing
 *   the corrected selection and only including `changes` when the doc
 *   actually differs.
 */
export function singleLineGuard(isMultiline: () => boolean): Extension {
  return EditorState.transactionFilter.of((tr) => {
    if (isMultiline() || !tr.docChanged) return tr;
    const text = tr.newDoc.toString();
    if (!/[\r\n]/.test(text)) return tr;
    const cleaned = text.replace(/[\r\n]+/g, "");
    const { anchor, head } = tr.newSelection.main;
    const shift = (pos: number) => Math.max(0, Math.min(pos - newlinesBefore(text, pos), cleaned.length));
    const selection = { anchor: shift(anchor), head: shift(head) };
    const preserved = {
      effects: tr.effects,
      annotations: knownAnnotations(tr),
      scrollIntoView: tr.scrollIntoView,
    };
    if (cleaned === tr.startState.doc.toString()) {
      // Nothing textual changes, but the selection still has to land where
      // a real edit would have — a paste that replaced a selection with
      // (once cleaned) the same text it already held must still collapse
      // the selection to the end of the paste, not leave the old range
      // standing open for the next keystroke to clobber.
      return { selection, ...preserved };
    }
    return {
      changes: { from: 0, to: tr.startState.doc.length, insert: cleaned },
      selection,
      ...preserved,
    };
  });
}

// src/components/codeEditorHighlight.ts — the highlighter codeEditor.tsx
// mounts, replacing `syntaxHighlighting(classHighlighter)`.
//
// WHY a hand-written `HighlightStyle` and not `classHighlighter` (the stock
// @lezer/highlight highlighter this replaces): `classHighlighter`'s own
// rule table (node_modules/@lezer/highlight/dist/index.js) has no entry for
// `controlKeyword`, `definitionKeyword`, `moduleKeyword`, `operatorKeyword`,
// or either `function(...)` combination, so @lezer/highlight's own
// specificity fallback (a tag's `.set`, most-specific first) walks past all
// of them to the nearest ancestor tag that DOES have one. Measured on this
// exact tree (@lezer/highlight 1.2.3, @codemirror/lang-python 6.2.1):
//   controlKeyword / definitionKeyword / moduleKeyword / operatorKeyword
//     all collapse to plain `tags.keyword` -> "tok-keyword"
//   a call site, `function(variableName)` (e.g. `range(x)`), collapses to
//     `tok-variableName`; a method call, `function(propertyName)`
//     (e.g. `obj.foo()`), collapses to `tok-propertyName`
//   a Python/JS function DEFINITION is `function(definition(variableName))`
//     — its `.set` chain visits `definition(variableName)` (which DOES
//     have a classHighlighter rule, "tok-variableName tok-definition")
//     BEFORE it ever reaches plain `function(variableName)`, so it collapses
//     there and never reaches a "tok-function" class at all, at any
//     specificity level `classHighlighter` covers.
// In Dark Modern (Zach: "its important that people can set it to what they
// are used to") that means `if`/`return`/`for` render keyword-blue
// (#569cd6) instead of the correct control-purple (#c586c0), and a function
// name renders variable-blue (#9cdcfe) instead of the correct yellow
// (#dcdcaa) — the two most recognisable VS Code colours, both wrong. See
// codeEditorTheme.ts's own WHY on `--bbox-tok-control-keyword`/
// `--bbox-tok-function`, which have carried the right values the whole time
// with nothing ever emitting a class to hang them on.
//
// This file is `classHighlighter`'s own rule list (transcribed verbatim
// below, one rule per line matching its source order) PLUS the missing
// rules, each one UNIONING its class string with whatever `classHighlighter`
// already produced for that exact tag rather than replacing it — never
// "tok-controlKeyword" alone, always "tok-keyword tok-controlKeyword". Two
// reasons, both load-bearing:
//   1. `HighlightStyle`/`tagHighlighter` picks ONE map entry per token — the
//      first match walking that token's tag `.set` from most to least
//      specific — so a rule for the exact composed tag (e.g.
//      `function(definition(variableName))`) must be its own entry with
//      every class the token needs; you cannot "layer" two separate,
//      differently-specific entries and get both.
//   2. codeEditor.css's selectors were written expecting `classHighlighter`-
//      shaped input (a bare token gets exactly one ancestor's class) and
//      groups `tok-keyword`/`tok-operatorKeyword`/`tok-definitionKeyword`/
//      `tok-moduleKeyword` under ONE rule for exactly this reason — keeping
//      the old class present alongside the new one means every rule that
//      already worked keeps working unchanged, with the new, more specific
//      selector (`tok-controlKeyword`, `tok-function`) simply winning the
//      cascade tie by appearing later in that file. Dropping the old class
//      would also fail this file's own H1 unit test, which asserts the new
//      highlighter's class set is a strict superset of `classHighlighter`'s
//      for every token in real Python/JS/JSON source.
import { HighlightStyle } from "@codemirror/language";
import { tags } from "@lezer/highlight";

export const codeEditorHighlightStyle = HighlightStyle.define([
  // --- verbatim from @lezer/highlight's classHighlighter (1.2.3), same order ---
  { tag: tags.link, class: "tok-link" },
  { tag: tags.heading, class: "tok-heading" },
  { tag: tags.emphasis, class: "tok-emphasis" },
  { tag: tags.strong, class: "tok-strong" },
  { tag: tags.keyword, class: "tok-keyword" },
  { tag: tags.atom, class: "tok-atom" },
  { tag: tags.bool, class: "tok-bool" },
  { tag: tags.url, class: "tok-url" },
  { tag: tags.labelName, class: "tok-labelName" },
  { tag: tags.inserted, class: "tok-inserted" },
  { tag: tags.deleted, class: "tok-deleted" },
  { tag: tags.literal, class: "tok-literal" },
  { tag: tags.string, class: "tok-string" },
  { tag: tags.number, class: "tok-number" },
  { tag: [tags.regexp, tags.escape, tags.special(tags.string)], class: "tok-string2" },
  { tag: tags.variableName, class: "tok-variableName" },
  { tag: tags.local(tags.variableName), class: "tok-variableName tok-local" },
  { tag: tags.definition(tags.variableName), class: "tok-variableName tok-definition" },
  { tag: tags.special(tags.variableName), class: "tok-variableName2" },
  { tag: tags.definition(tags.propertyName), class: "tok-propertyName tok-definition" },
  { tag: tags.typeName, class: "tok-typeName" },
  { tag: tags.namespace, class: "tok-namespace" },
  { tag: tags.className, class: "tok-className" },
  { tag: tags.macroName, class: "tok-macroName" },
  { tag: tags.propertyName, class: "tok-propertyName" },
  { tag: tags.operator, class: "tok-operator" },
  { tag: tags.comment, class: "tok-comment" },
  { tag: tags.meta, class: "tok-meta" },
  { tag: tags.invalid, class: "tok-invalid" },
  { tag: tags.punctuation, class: "tok-punctuation" },

  // --- the rules classHighlighter is missing (this file's own WHY above) ---
  // Bare keyword subtags: each already falls under codeEditor.css's shared
  // `.tok-keyword, .tok-operatorKeyword, .tok-definitionKeyword,
  // .tok-moduleKeyword` selector, so keeping "tok-keyword" alongside the
  // specific class changes nothing about which rule matches for these
  // three — only `tok-controlKeyword` has its own separate CSS rule.
  { tag: tags.controlKeyword, class: "tok-keyword tok-controlKeyword" },
  { tag: tags.definitionKeyword, class: "tok-keyword tok-definitionKeyword" },
  { tag: tags.moduleKeyword, class: "tok-keyword tok-moduleKeyword" },
  { tag: tags.operatorKeyword, class: "tok-keyword tok-operatorKeyword" },
  // A function name at a call site (`range(x)`, `obj.foo()`): the bare
  // `function(...)` tag, one level more specific than classHighlighter's
  // own `variableName`/`propertyName` entries above.
  { tag: tags.function(tags.variableName), class: "tok-variableName tok-function" },
  { tag: tags.function(tags.propertyName), class: "tok-propertyName tok-function" },
  // A function/method DEFINITION (`def move(...)`, `function move(...)`):
  // its own most-specific entry, since `function(definition(variableName))`'s
  // `.set` chain reaches `definition(variableName)` (mapped above) before it
  // ever reaches the bare `function(variableName)` rule two lines up — see
  // this file's own WHY, point 1.
  {
    tag: tags.function(tags.definition(tags.variableName)),
    class: "tok-variableName tok-definition tok-function",
  },
  {
    tag: tags.function(tags.definition(tags.propertyName)),
    class: "tok-propertyName tok-definition tok-function",
  },
]);

// src/components/codeEditorLayout.ts — the columns → pixel-width maths,
// recovered from claude/code-block-primitive's packages/bbox-ui/src/
// codeBlock.layout.ts (`CODE_BLOCK_GUTTER_PX`, `CODE_BLOCK_CHAR_RATIO`,
// `codeBlockCharPx`, `codeBlockWidthPx`) after main's 368a524 dropped the
// whole `look`/preset ladder that file also carried. Trimmed to just the
// width maths — no size ladder, no look/overflow enum, no `grow`/
// `grow-truncated` (this app has no FieldSpec/preset machinery to hang
// those on). Pure numbers, no React, no CodeMirror.
//
// DONOR LINES (branch `claude/code-block-primitive`, tip dc30352, read
// 2026-09-17 — the branch is unmerged but present, so `git show
// claude/code-block-primitive:packages/bbox-ui/src/codeBlock.layout.ts`
// resolves these offline):
//   • `:111` `CODE_BLOCK_GUTTER_PX = 36`  -> `CODE_EDITOR_GUTTER_PX`
//   • `:112` `CODE_BLOCK_CHAR_RATIO = 0.61` -> `CODE_EDITOR_CHAR_RATIO`
//   • `:116` `codeBlockCharPx` body        -> `codeEditorCharPx`
//   • `:135` `codeBlockWidthPx` body       -> `codeEditorWidthPx`
// Renames only; the arithmetic is byte-identical. main's 368a524 is the
// commit that dropped the rest of that file.
//
// NO PRIOR ART IS CLAIMED. `0.61` is an EMPIRICAL constant — a measured
// glyph-advance ratio for one specific font stack, not a derived or
// published figure — and the width formula is plain addition. The honest
// caveat that goes with an empirical constant: it is only right for the
// `ui-monospace` stack it was measured on, and a host that swaps the font
// silently gets a wrong width. That is a known limitation, not a bug being
// reported here.

/** The line-number gutter's reserved width, and the mono-cell approximation
 * (glyph advance ≈ 0.61 × font-size for the ui-monospace stack) — both
 * SystemSketch's own measured constants, ported via codeBlock.layout.ts. */
export const CODE_EDITOR_GUTTER_PX = 36;
export const CODE_EDITOR_CHAR_RATIO = 0.61;

/** Width in px of one character cell at `fontPx`. */
export function codeEditorCharPx(fontPx: number): number {
  return Math.max(1, fontPx * CODE_EDITOR_CHAR_RATIO);
}

/**
 * The box width a CodeEditor takes to show `columns` characters — padding,
 * plus the gutter when line numbers are on, plus the cells. `columns` is
 * the AUTHORED fact ("100 ch"), pixels derive from it, never the other way
 * round. Returns `undefined` for `columns <= 0`, the "fill whatever the
 * host gives me" default.
 */
export function codeEditorWidthPx(
  columns: number,
  fontPx: number,
  lineNumbers: boolean,
  paddingLeft: number,
  paddingRight: number,
): number | undefined {
  if (!Number.isFinite(columns) || columns <= 0) return undefined;
  return Math.round(
    paddingLeft +
      paddingRight +
      (lineNumbers ? CODE_EDITOR_GUTTER_PX : 0) +
      Math.round(columns) * codeEditorCharPx(fontPx),
  );
}

// src/components/codeEditorTheme.ts — the palette-swap half of syntax
// theming (docs/FEEDBACK-2026-09-17b-PLAN.md A-2). `codeEditor.tsx` mounts
// `syntaxHighlighting(classHighlighter)` once and never touches it again;
// `classHighlighter` (@lezer/highlight) emits stable, colourless `tok-*`
// classes, and codeEditor.css is the one place those get a colour — under
// selectors that read `var(--bbox-tok-*, <today's literal>)`. A theme is
// therefore nothing but a map of those custom-property names to hex
// strings, applied inline on the editor root: no second highlighter, no
// per-theme `EditorView.theme()`. Pure data + one small resolver, no React
// import needed beyond the `CSSProperties` return type.
//
// WHY a palette swap and not a CodeMirror theme extension: `EditorView.theme()`
// reconfigures CodeMirror's own stylesheet machinery per instance — four
// themes would mean four compartmented extensions, reconciled against
// whatever `classHighlighter` already painted, fighting the same cascade
// this file's sibling CSS already resolved once (codeEditor.css's own WHY
// on selector specificity). A CSS variable is one inline `style` write, no
// CodeMirror reconfiguration, and it composes with a caller's own `style`
// override for free.
import type { CSSProperties } from "react";

export interface CodeEditorTheme {
  /** Stable id — what a `theme` prop or a `<select>`'s `value` carries. */
  id: string;
  /** Human label, e.g. "Dark Modern". */
  label: string;
  appearance: "dark" | "light";
  /** CSS custom properties (`--bbox-tok-*`), applied inline to the editor root. */
  vars: Record<string, string>;
}

